// ---------------------------------------------------------------------------
// Unit tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_principal_builds_with_defaults() {
        let p = a_principal().build();
        assert_eq!(p.principal_key(), "user:test");
        assert!(p.display_name().is_none());
    }

    #[test]
    fn a_tag_registry_entry_builds_with_defaults() {
        let t = a_tag_registry_entry().build();
        assert_eq!(t.tag(), "test-tag");
    }

    #[test]
    fn a_similar_item_builds_with_defaults() {
        let s = a_similar_item().build();
        assert!((s.similarity_score() - 0.85).abs() < f32::EPSILON);
        assert_eq!(s.suggested_relation(), RelationSuggestion::Supports);
    }

    #[test]
    fn a_project_builds_with_defaults() {
        let project = a_project().build();
        assert_eq!(project.name(), "test-project");
        assert_eq!(project.default_branch(), "main");
    }

    #[test]
    fn a_project_allows_field_override() {
        let project = a_project().name("custom".to_owned()).build();
        assert_eq!(project.name(), "custom");
        assert_eq!(project.default_branch(), "main");
    }

    #[test]
    fn a_knowledge_item_builds_with_defaults() {
        let item = a_knowledge_item().build();
        assert_eq!(item.kind(), KnowledgeKind::Heuristic);
        assert_eq!(item.content(), "test knowledge content");
        assert_eq!(item.confidence(), Confidence::Inferred);
    }

    #[test]
    fn a_job_builds_with_defaults() {
        let job = a_job().build();
        assert_eq!(job.status(), JobStatus::Queued);
        assert!(job.outcome().is_none());
    }

    #[test]
    fn a_reference_builds_with_defaults() {
        let r = a_reference().build();
        assert_eq!(r.kind(), ReferenceKind::FilePath);
        assert_eq!(r.value(), "//src/lib.rs");
    }

    #[test]
    fn a_embedding_builds_with_defaults() {
        let e = a_embedding().build();
        assert_eq!(e.model(), "nomic-embed-text:v1.5");
        assert_eq!(e.dimensions(), 384);
        assert_eq!(e.embedding().len(), 384);
    }

    #[test]
    fn a_knowledge_item_relation_builds_with_defaults() {
        let r = a_knowledge_item_relation().build();
        assert_eq!(r.relation_type(), RelationKind::Supports);
    }

    #[test]
    fn a_item_observation_builds_with_defaults() {
        let o = a_item_observation().build();
        assert_eq!(o.source_type(), SourceType::AgentMediated);
    }

    #[test]
    fn a_triage_similar_item_decision_builds_with_defaults() {
        let d = a_triage_similar_item_decision().build();
        assert_eq!(d.suggested_relation(), RelationSuggestion::Supports);
        assert_eq!(d.justification_text(), "test justification");
    }

    #[test]
    fn a_triage_result_created_builds_with_defaults() {
        let r = a_triage_result_created().build();
        assert!(matches!(r.outcome(), TriageOutcome::Created { .. }));
    }

    #[test]
    fn a_triage_result_duplicate_builds_with_defaults() {
        let r = a_triage_result_duplicate().build();
        assert!(matches!(r.outcome(), TriageOutcome::Duplicate { .. }));
    }

    #[test]
    fn a_triage_result_failed_builds_with_defaults() {
        let r = a_triage_result_failed().build();
        assert!(matches!(
            r.outcome(),
            TriageOutcome::Failed {
                retryable: false,
                ..
            }
        ));
    }

    #[test]
    fn a_retrieval_feedback_builds_with_defaults() {
        let f = a_retrieval_feedback().build();
        assert_eq!(f.rating(), FeedbackRating::Positive);
        assert_eq!(f.query_text(), "test query");
    }

    #[test]
    fn a_auth_token_builds_with_defaults() {
        let t = a_auth_token().build();
        assert_eq!(t.token_hash().len(), 64);
        assert!(t.revoked_at().is_none());
    }

    #[test]
    fn a_prompt_version_builds_with_defaults() {
        let pv = a_prompt_version().build();
        assert_eq!(pv.stage(), PromptStage::Extraction);
        assert_eq!(pv.content(), "test prompt content");
    }

    #[test]
    fn a_token_usage_builds_with_defaults() {
        let tu = a_token_usage().build();
        assert_eq!(tu.stage(), PipelineStage::Extraction);
        assert_eq!(tu.tokens_total(), 150);
    }

    #[test]
    fn a_task_builds_with_defaults() {
        let t = a_task().build();
        assert_eq!(t.task_type(), TaskType::Extraction);
        assert_eq!(t.status(), TaskStatus::Queued);
        assert_eq!(t.retry_count(), 0);
    }

    #[test]
    fn a_standing_builds_with_defaults() {
        let s = a_standing().build();
        assert_eq!(s.supporting_count(), 0);
        assert_eq!(s.observation_count(), 1);
        assert!(s.superseded_by().is_none());
    }
}
